import json
import sys
import os
import re
from decimal import Decimal

def read_json_data(data_file):
    cache_file = f"{data_file}.cache"
    if os.path.exists(cache_file):
        with open(cache_file, 'r') as f:
            return json.load(f)
    with open(data_file, 'r') as f:
        data = json.load(f)
        with open(cache_file, 'w') as f:
            json.dump(data, f)
        return data

def render_template(template_path, data):
    with open(template_path, 'r') as f:
        template_content = f.read()

    def replace_placeholders(match):
        key = match.group(1)
        value = data.get(key)
        if value is None:
            return match.group(0)

        if isinstance(value, bool):
            return str(value).lower()
        elif isinstance(value, (int, float)):
            return str(value)
        elif isinstance(value, str):
            return value
        elif value is None:
            return ""
        else:
            return str(value)

    def evaluate_expression(expr):
        try:
            # Replace JSON keys with their numeric values
            for key in data:
                if isinstance(data[key], (int, float)):
                    expr = expr.replace(key, str(data[key]))
            # Evaluate the expression safely
            result = eval(expr, {'__builtins__': None}, {})
            return f"{result:.2f}"
        except:
            return ""

    # Replace simple placeholders
    template_content = re.sub(r'\{\{(.*?)\}\}', replace_placeholders, template_content)

    # Replace arithmetic expressions
    template_content = re.sub(r'\{\{=(.*?)\}\}', evaluate_expression, template_content)

    return template_content

def main():
    if len(sys.argv) != 4:
        print("Usage: python report_tool.py <data_file.json> <template.html> <output.html>")
        sys.exit(1)

    data_file = sys.argv[1]
    template_file = sys.argv[2]
    output_file = sys.argv[3]

    data = read_json_data(data_file)
    rendered_html = render_template(template_file, data)

    with open(output_file, 'w') as f:
        f.write(rendered_html)

if __name__ == "__main__":
    main()
